-- TapRide - Initial Database Schema (Issue #19)
-- Target: PostgreSQL 15+
--
-- Reference design for the TapRide Digital Wallet and Bus Management System,
-- derived from the approved SRS (EER4189 Project Proposal, section 3) and the
-- wallet notes in backend/wallet_db.py (Issue #25).
--
-- This file documents the initial schema. Runtime connection handling and
-- migration tooling are handled separately (Issue #18).
--
-- Conventions
--   * Surrogate primary keys: BIGINT GENERATED BY DEFAULT AS IDENTITY.
--   * Idempotency / external references: UUID (`reference`, `client_event_id`).
--   * Money: NUMERIC(12,2) in LKR. Never float.
--   * Timestamps: TIMESTAMPTZ, stored in UTC.
--   * Enumerations: TEXT + CHECK constraints (simpler than PG ENUM for a prototype).
--   * Personal data (NIC, mobile) is encrypted at the application layer (AES-256-GCM);
--     the columns below hold the resulting envelope, never plaintext.
--
-- No extensions are required: `gen_random_uuid()` is built into PostgreSQL 13+
-- and the target platform is PostgreSQL 15 (SRS 4.1.2).

-- ---------------------------------------------------------------------------
-- 1. Identity and roles
-- ---------------------------------------------------------------------------

CREATE TABLE users (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    role            TEXT NOT NULL
                    CHECK (role IN ('passenger', 'conductor', 'driver', 'owner', 'admin')),
    full_name       TEXT NOT NULL,
    mobile          TEXT NOT NULL UNIQUE,
    email           TEXT UNIQUE,
    nic             TEXT UNIQUE,
    password_hash   TEXT NOT NULL,
    status          TEXT NOT NULL DEFAULT 'active'
                    CHECK (status IN ('active', 'pending', 'suspended')),
    last_login_at   TIMESTAMPTZ,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX idx_users_role_status ON users (role, status);

-- Passenger profile (1:1 with users). Kept separate from crew/owner profiles so
-- wallet ownership and personal data stay scoped to passengers.
CREATE TABLE passengers (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id     BIGINT NOT NULL UNIQUE REFERENCES users (id) ON DELETE CASCADE,
    email       TEXT NOT NULL UNIQUE,
    nic         TEXT,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- ---------------------------------------------------------------------------
-- 2. Wallet
-- ---------------------------------------------------------------------------

-- balance        = funds owned by the passenger (top-ups, refunds, adjustments)
-- held_balance   = maximum-fare holds for open journeys (FR-10)
-- available_balance = balance - held_balance (FR-5), generated by PostgreSQL
CREATE TABLE wallets (
    id                 BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    passenger_id       BIGINT NOT NULL UNIQUE REFERENCES passengers (id) ON DELETE CASCADE,
    balance            NUMERIC(12,2) NOT NULL DEFAULT 0 CHECK (balance >= 0),
    held_balance       NUMERIC(12,2) NOT NULL DEFAULT 0 CHECK (held_balance >= 0),
    currency           CHAR(3) NOT NULL DEFAULT 'LKR',
    status             TEXT NOT NULL DEFAULT 'active'
                       CHECK (status IN ('active', 'suspended', 'closed')),
    created_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
    available_balance  NUMERIC(12,2) GENERATED ALWAYS AS (balance - held_balance) STORED,
    CONSTRAINT wallets_hold_within_balance CHECK (held_balance <= balance)
);

CREATE INDEX idx_wallets_status ON wallets (status);

-- ---------------------------------------------------------------------------
-- 3. Fleet, crew and routes
-- ---------------------------------------------------------------------------

CREATE TABLE bus_owners (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id         BIGINT NOT NULL UNIQUE REFERENCES users (id) ON DELETE CASCADE,
    business_name   TEXT NOT NULL,
    brn             TEXT UNIQUE,
    contact_phone   TEXT,
    status          TEXT NOT NULL DEFAULT 'pending'
                    CHECK (status IN ('pending', 'approved', 'rejected', 'suspended')),
    approved_by     BIGINT REFERENCES users (id),
    approved_at     TIMESTAMPTZ,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE routes (
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    route_code   TEXT NOT NULL UNIQUE,
    name         TEXT NOT NULL,
    origin       TEXT,
    destination  TEXT,
    distance_km  NUMERIC(6,2) CHECK (distance_km > 0),
    status       TEXT NOT NULL DEFAULT 'active'
                 CHECK (status IN ('active', 'inactive')),
    created_by   BIGINT REFERENCES users (id),
    created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at   TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE route_stages (
    id                       BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    route_id                 BIGINT NOT NULL REFERENCES routes (id) ON DELETE CASCADE,
    stage_order              SMALLINT NOT NULL CHECK (stage_order > 0),
    name                     TEXT NOT NULL,
    distance_from_origin_km  NUMERIC(6,2) CHECK (distance_from_origin_km >= 0),
    CONSTRAINT uq_route_stage_order UNIQUE (route_id, stage_order),
    CONSTRAINT uq_route_stage_name UNIQUE (route_id, name),
    CONSTRAINT uq_route_stage_identity UNIQUE (route_id, id)
);

CREATE TABLE stage_fares (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    route_id        BIGINT NOT NULL,
    entry_stage_id  BIGINT NOT NULL,
    exit_stage_id   BIGINT NOT NULL,
    fare_amount     NUMERIC(12,2) NOT NULL CHECK (fare_amount > 0),
    effective_from  DATE NOT NULL DEFAULT CURRENT_DATE,
    effective_to    DATE,
    created_by      BIGINT REFERENCES users (id),
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT fk_stage_fares_entry
        FOREIGN KEY (route_id, entry_stage_id) REFERENCES route_stages (route_id, id),
    CONSTRAINT fk_stage_fares_exit
        FOREIGN KEY (route_id, exit_stage_id) REFERENCES route_stages (route_id, id),
    CONSTRAINT chk_stage_fares_distinct CHECK (entry_stage_id <> exit_stage_id),
    CONSTRAINT chk_stage_fares_window
        CHECK (effective_to IS NULL OR effective_to >= effective_from),
    CONSTRAINT uq_stage_fare_window
        UNIQUE (route_id, entry_stage_id, exit_stage_id, effective_from)
);

CREATE INDEX idx_stage_fares_lookup
    ON stage_fares (route_id, entry_stage_id, exit_stage_id);

CREATE TABLE buses (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    owner_id        BIGINT NOT NULL REFERENCES bus_owners (id) ON DELETE CASCADE,
    plate_number    TEXT NOT NULL UNIQUE,
    chassis_number  TEXT UNIQUE,
    route_id        BIGINT REFERENCES routes (id) ON DELETE SET NULL,
    seat_capacity   SMALLINT NOT NULL CHECK (seat_capacity > 0),
    status          TEXT NOT NULL DEFAULT 'pending'
                    CHECK (status IN ('pending', 'active', 'inactive', 'suspended')),
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX idx_buses_owner ON buses (owner_id, status);

CREATE TABLE crew_members (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id         BIGINT NOT NULL UNIQUE REFERENCES users (id) ON DELETE CASCADE,
    crew_role       TEXT NOT NULL CHECK (crew_role IN ('conductor', 'driver')),
    license_number  TEXT,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT chk_driver_license CHECK (crew_role <> 'driver' OR license_number IS NOT NULL)
);

CREATE TABLE crew_assignments (
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    crew_id      BIGINT NOT NULL REFERENCES crew_members (id) ON DELETE CASCADE,
    bus_id       BIGINT NOT NULL REFERENCES buses (id) ON DELETE CASCADE,
    assigned_from DATE NOT NULL,
    assigned_to   DATE,
    assigned_by   BIGINT REFERENCES users (id),
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT chk_assignment_window CHECK (assigned_to IS NULL OR assigned_to >= assigned_from),
    CONSTRAINT uq_crew_bus_start UNIQUE (crew_id, bus_id, assigned_from)
);

CREATE INDEX idx_crew_assignments_bus ON crew_assignments (bus_id, assigned_to);

-- ---------------------------------------------------------------------------
-- 4. Journeys, holds and ledger
-- ---------------------------------------------------------------------------

CREATE TABLE journeys (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    reference       UUID NOT NULL UNIQUE DEFAULT gen_random_uuid(),
    passenger_id    BIGINT NOT NULL REFERENCES passengers (id) ON DELETE RESTRICT,
    wallet_id       BIGINT NOT NULL REFERENCES wallets (id) ON DELETE RESTRICT,
    bus_id          BIGINT NOT NULL REFERENCES buses (id) ON DELETE RESTRICT,
    route_id        BIGINT NOT NULL REFERENCES routes (id) ON DELETE RESTRICT,
    entry_stage_id  BIGINT NOT NULL REFERENCES route_stages (id) ON DELETE RESTRICT,
    exit_stage_id   BIGINT REFERENCES route_stages (id) ON DELETE RESTRICT,
    conductor_id    BIGINT REFERENCES crew_members (id) ON DELETE SET NULL,
    entry_time      TIMESTAMPTZ NOT NULL DEFAULT now(),
    exit_time       TIMESTAMPTZ,
    hold_amount     NUMERIC(12,2) NOT NULL DEFAULT 0 CHECK (hold_amount >= 0),
    fare_amount     NUMERIC(12,2) CHECK (fare_amount >= 0),
    status          TEXT NOT NULL DEFAULT 'initiated'
                    CHECK (status IN ('initiated', 'in_progress', 'pending_sync',
                                      'completed', 'exception')),
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT chk_journey_times CHECK (exit_time IS NULL OR exit_time >= entry_time)
);

-- A passenger may only have one open journey at a time (FR-9/FR-14).
CREATE UNIQUE INDEX uq_journey_open_per_passenger
    ON journeys (passenger_id)
    WHERE status IN ('initiated', 'in_progress', 'pending_sync');

CREATE INDEX idx_journeys_passenger_time ON journeys (passenger_id, entry_time DESC);
CREATE INDEX idx_journeys_bus_time ON journeys (bus_id, entry_time DESC);
CREATE INDEX idx_journeys_status ON journeys (status);

CREATE TABLE wallet_holds (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    wallet_id   BIGINT NOT NULL REFERENCES wallets (id) ON DELETE CASCADE,
    journey_id  BIGINT NOT NULL UNIQUE REFERENCES journeys (id) ON DELETE CASCADE,
    amount      NUMERIC(12,2) NOT NULL CHECK (amount > 0),
    status      TEXT NOT NULL DEFAULT 'active'
                CHECK (status IN ('active', 'released', 'captured')),
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    released_at TIMESTAMPTZ
);

CREATE INDEX idx_wallet_holds_wallet ON wallet_holds (wallet_id, status);

CREATE TABLE wallet_transactions (
    id             BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    wallet_id      BIGINT NOT NULL REFERENCES wallets (id) ON DELETE CASCADE,
    journey_id     BIGINT REFERENCES journeys (id) ON DELETE SET NULL,
    type           TEXT NOT NULL
                   CHECK (type IN ('topup', 'fare', 'refund', 'hold',
                                   'hold_release', 'adjustment')),
    amount         NUMERIC(12,2) NOT NULL CHECK (amount > 0),
    balance_after  NUMERIC(12,2) NOT NULL CHECK (balance_after >= 0),
    status         TEXT NOT NULL DEFAULT 'completed'
                   CHECK (status IN ('pending', 'completed', 'failed')),
    reference      UUID UNIQUE DEFAULT gen_random_uuid(),
    description    TEXT,
    created_at     TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX idx_wallet_tx_wallet_time ON wallet_transactions (wallet_id, created_at DESC);
CREATE INDEX idx_wallet_tx_journey ON wallet_transactions (journey_id);

-- ---------------------------------------------------------------------------
-- 5. Offline sync and audit
-- ---------------------------------------------------------------------------

-- `client_event_id` is the UUID generated on the device (FR-16) and is the
-- idempotency key for sync retries (FR-17/FR-18).
CREATE TABLE journey_events (
    id               BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    client_event_id  UUID NOT NULL UNIQUE,
    journey_id       BIGINT REFERENCES journeys (id) ON DELETE CASCADE,
    event_type       TEXT NOT NULL
                     CHECK (event_type IN ('entry_scan', 'exit_scan',
                                           'conductor_exit', 'manual_ticket')),
    payload          JSONB NOT NULL DEFAULT '{}'::jsonb,
    device_id        TEXT,
    status           TEXT NOT NULL DEFAULT 'pending'
                     CHECK (status IN ('pending', 'synced', 'failed')),
    occurred_at      TIMESTAMPTZ NOT NULL,
    synced_at        TIMESTAMPTZ,
    created_at       TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX idx_journey_events_status ON journey_events (status, occurred_at);
CREATE INDEX idx_journey_events_journey ON journey_events (journey_id);

CREATE TABLE audit_logs (
    id             BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    actor_user_id  BIGINT REFERENCES users (id) ON DELETE SET NULL,
    action         TEXT NOT NULL,
    entity_type    TEXT NOT NULL,
    entity_id      TEXT NOT NULL,
    before_data    JSONB,
    after_data     JSONB,
    created_at     TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX idx_audit_entity ON audit_logs (entity_type, entity_id);
CREATE INDEX idx_audit_created ON audit_logs (created_at DESC);

-- ---------------------------------------------------------------------------
-- 6. updated_at maintenance
-- ---------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION set_updated_at()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = now();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DO $$
DECLARE
    target TEXT;
BEGIN
    FOREACH target IN ARRAY ARRAY['users', 'bus_owners', 'routes', 'buses', 'journeys', 'wallets']
    LOOP
        EXECUTE format(
            'CREATE TRIGGER trg_%1$s_updated_at
             BEFORE UPDATE ON %1$s
             FOR EACH ROW EXECUTE FUNCTION set_updated_at()', target);
    END LOOP;
END;
$$;
